<template><div class="page"><div class="page-head"><div><h2>库存流水</h2><p class="muted">追踪入库、出库、订单扣减与取消返还。</p></div><el-button type="primary" @click="visible=true">调整库存</el-button></div><section class="panel filters"><el-select v-model="filters.dessertId" clearable placeholder="全部甜品"><el-option v-for="d in desserts" :key="d.id" :label="d.name" :value="d.id"/></el-select><el-select v-model="filters.type" clearable placeholder="全部类型"><el-option v-for="t in types" :key="t.value" :label="t.label" :value="t.value"/></el-select><el-button type="primary" @click="search">查询</el-button></section><section class="panel"><el-table :data="result.records" v-loading="loading"><el-table-column prop="dessertName" label="甜品"/><el-table-column label="类型"><template #default="{row}"><el-tag>{{text(row.type)}}</el-tag></template></el-table-column><el-table-column label="变化"><template #default="{row}"><strong :class="row.changeQuantity>0?'in':'out'">{{row.changeQuantity>0?'+':''}}{{row.changeQuantity}}</strong></template></el-table-column><el-table-column label="库存"><template #default="{row}">{{row.beforeStock}} → {{row.afterStock}}</template></el-table-column><el-table-column prop="orderNo" label="订单号"/><el-table-column prop="remark" label="原因" min-width="220"/><el-table-column prop="createTime" label="时间" min-width="180"/></el-table><el-pagination class="pager" background layout="total,prev,pager,next" :total="result.total" :page-size="filters.size" v-model:current-page="filters.page" @current-change="load"/></section><el-dialog v-model="visible" title="调整库存" width="480px"><el-form label-position="top"><el-form-item label="甜品"><el-select v-model="form.dessertId"><el-option v-for="d in desserts" :key="d.id" :label="`${d.name} · 库存 ${d.stock}`" :value="d.id"/></el-select></el-form-item><el-form-item label="方向"><el-radio-group v-model="form.direction"><el-radio-button value="IN">入库</el-radio-button><el-radio-button value="OUT">出库</el-radio-button></el-radio-group></el-form-item><el-form-item label="数量"><el-input-number v-model="form.quantity" :min="1" :precision="0"/></el-form-item><el-form-item label="原因"><el-input v-model="form.remark" placeholder="采购入库、门店损耗等"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">确认</el-button></template></el-dialog></div></template>
<script setup>
import {onMounted,reactive,ref} from 'vue';import{ElMessage}from'element-plus';import{pageDesserts}from'../api/dessert';import{pageStockRecords,adjustStock}from'../api/stock'
const types=[{value:'MANUAL_IN',label:'手动入库'},{value:'MANUAL_OUT',label:'手动出库'},{value:'ORDER_OUT',label:'订单扣减'},{value:'ORDER_RETURN',label:'订单返还'}],desserts=ref([]),result=reactive({records:[],total:0}),filters=reactive({page:1,size:10,dessertId:null,type:''}),form=reactive({dessertId:null,direction:'IN',quantity:1,remark:''}),loading=ref(false),saving=ref(false),visible=ref(false),text=v=>types.find(x=>x.value===v)?.label||v
async function load(){loading.value=true;try{Object.assign(result,await pageStockRecords(filters))}catch(e){ElMessage.error(e.message)}finally{loading.value=false}} function search(){filters.page=1;load()}
async function save(){if(!form.dessertId||!form.remark.trim()){ElMessage.warning('请选择甜品并填写原因');return}saving.value=true;try{await adjustStock(form);ElMessage.success('库存调整成功');visible.value=false;desserts.value=(await pageDesserts({page:1,size:100})).records;await load()}catch(e){ElMessage.error(e.message)}finally{saving.value=false}}
onMounted(async()=>{desserts.value=(await pageDesserts({page:1,size:100})).records;await load()})</script>
<style scoped>.filters{display:grid;grid-template-columns:1.5fr 1fr auto;gap:12px}.filters .el-select,.el-form .el-select{width:100%}.pager{justify-content:flex-end;margin-top:18px}.in{color:#67c23a}.out{color:#f56c6c}@media(max-width:700px){.filters{grid-template-columns:1fr}}</style>
